LOG_EVERY = 25


def lr_at(frac):
    """Time-based schedule: linear warmup then cosine decay, frac = elapsed / budget."""
    frac = min(max(frac, 0.0), 1.0)
    if frac < WARMUP_FRAC:
        return LR * max(frac / WARMUP_FRAC, 0.02)
    p = (frac - WARMUP_FRAC) / (1.0 - WARMUP_FRAC)
    return LR * (MIN_LR_FRAC + (1.0 - MIN_LR_FRAC) * 0.5 * (1.0 + math.cos(math.pi * p)))

